import { JSXElement, ParentComponent, Show } from "solid-js";

import { Divider } from "#core/ui-next/components/divider.jsx";
import { ImageCacheTrigger } from "#core/ui-next/components/image-cache.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ThrobberSuspense } from "#core/ui-next/components/throbber.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { isMobile } from "#core/ui-next/services/view-experience.js";

export interface CommerceScreenBaseTabContentProps {
	title?: string;
	description: string;
	headerBar?: JSXElement;
}
const CommerceScreenBaseTabContentComponent: ParentComponent<CommerceScreenBaseTabContentProps> = (props) => {
	return (
		<>
			<div class={`text-base w-full text-center my-4 ${isMobile() ? "px-6" : ""}`}>
				<L10n.Compose text={props.description} />
			</div>
			<div
				class={`flex flex-col flex-auto items-center mx-8 ${isMobile() && IsControllerActive() ? "mb-13" : "mb-5"} pl-8 pr-8 pt-2 relative`}
				style={{
					"background-color": "rgba(5, 7, 13,0.8)",
				}}
			>
				<div
					class="absolute h-6 -top-0\.5 -left-1\.5 -right-1\.5"
					style={{
						"border-image-source": "url(blp:hud_section-line)",
						"border-image-slice": "4 32 0 32 fill",
						"border-image-width": "auto",
					}}
				/>
				<ThrobberSuspense class="size-full">
					<ImageCacheTrigger />
					<div
						class="flex flex-col flex-auto pb-4 relative w-full"
						data-name="commerce-screen-base-tab-content"
					>
						<Show
							when={props.title}
							fallback={
								<Show when={props.headerBar}>
									<div class="flex flex-col w-full min-h-6">
										{props.headerBar}
										<Divider.Horizontal margin={2} />
									</div>
								</Show>
							}
						>
							{(title) => (
								<div class="flex flex-col w-full">
									<div class="flex flex-row w-full items-center">
										<div class="grow text-secondary uppercase font-title">
											<L10n.Compose text={title()} />
										</div>
										{props.headerBar}
									</div>
									<Divider.Horizontal margin={2} />
								</div>
							)}
						</Show>
						{props.children}
					</div>
				</ThrobberSuspense>
				<div
					class="absolute h-6 -bottom-0\.5 -left-1\.5 -right-1\.5 -scale-y-100"
					style={{
						"border-image-source": "url(blp:hud_section-line)",
						"border-image-slice": "4 32 0 32 fill",
						"border-image-width": "auto",
					}}
				/>
			</div>
		</>
	);
};

export const CommerceScreenBaseTabContent = ComponentRegistry.register({
	name: "CommerceScreenBaseTabContent",
	createInstance: CommerceScreenBaseTabContentComponent,
	images: ["blp:hud_section-line"],
});
